class GenerationError(ValueError):
    pass


def require(condition, message):
    if not condition:
        raise GenerationError(message)


def job_span(lines, job):
    """[start, end) line indexes of one job of the workflow text."""
    start = [i for i, text in enumerate(lines) if text == f'  {job}:']
    require(len(start) == 1, f'Job {job} not found exactly once')
    end = next((i for i in range(start[0] + 1, len(lines))
                if lines[i].startswith('  ') and not lines[i].startswith('   ') and lines[i].strip()), len(lines))
    return start[0], end


def step_span(lines, job, name):
    """[start, end) line indexes of one named step of one job."""
    start, end = job_span(lines, job)
    found = [i for i in range(start, end) if lines[i] == f'    - name: {name}']
    require(len(found) == 1, f'Step {name!r} not found exactly once in job {job}')
    following = next((i for i in range(found[0] + 1, end) if lines[i].startswith('    - ')), end)
    return found[0], following


def edit_step(text, job, name, old, new, count):
    lines = text.split('\n')
    start, end = step_span(lines, job, name)
    body = '\n'.join(lines[start:end])
    require(body.count(old) == count, f'Expected {count} occurrence(s) of {old!r} in step {name!r}, found {body.count(old)}')
    return '\n'.join(lines[:start] + body.replace(old, new).split('\n') + lines[end:])


def insert_after(text, job, after, step):
    lines = text.split('\n')
    start, end = job_span(lines, job)
    found = [i for i in range(start, end) if lines[i] == f'    - name: {after}']
    require(len(found) == 1, f'Step {after!r} not found exactly once in job {job}')
    following = next((i for i in range(found[0] + 1, end) if lines[i].startswith('    - ')), end)
    return '\n'.join(lines[:following] + step.rstrip('\n').split('\n') + lines[following:])


def generate(source_text):
    text = source_text
    for old, new, count in REPLACEMENTS:
        require(text.count(old) == count, f'Expected {count} occurrence(s) of {old.splitlines()[0]!r} in the standard '
                f'workflow, found {text.count(old)}')
        text = text.replace(old, new)
    require('standard_delivery.py' not in text and 'ipa-delivery' not in text and "'refs/heads/Claude'" not in text,
            'A reference to the common line remains in the generated workflow')
    for job, name, old, new, count in STEP_EDITS:
        text = edit_step(text, job, name, old, new, count)
    for job, after, step in INSERTIONS:
        text = insert_after(text, job, after, step)
    return text


def step_names(spec, job):
    return [step.get('name') for step in spec['jobs'][job]['steps']]


def explain(source_text, target_text, load):
    """The differences between the two parsed workflows, checked to be exactly the declared ones."""
    common, generated = load(source_text), load(target_text)
    require(list(common['jobs']) == list(generated['jobs']), 'The jobs differ')
    inserted = {}
    for job in common['jobs']:
        before, after = step_names(common, job), step_names(generated, job)
        added = [name for name in after if name not in before]
        require([name for name in after if name in before] == before, f'Steps of {job} were removed or reordered')
        require(added == [step.split('\n')[0].removeprefix('    - name: ') for j, _, step in INSERTIONS if j == job],
                f'Unexpected inserted steps in {job}: {added}')
        inserted[job] = added
        kept = {step['name']: step for step in generated['jobs'][job]['steps']}
        edits = {(name, old): (new, count) for j, name, old, new, count in STEP_EDITS if j == job}
        for step in common['jobs'][job]['steps']:
            expected = json.loads(json.dumps(step).replace(COMMON_CALL, LINE_CALL))
            for (name, old), (new, count) in edits.items():
                if name == step['name']:
                    require(expected['run'].count(old) == count, f'Declared edit {old!r} of {name!r} does not apply')
                    expected['run'] = expected['run'].replace(old, new)
            require(kept[step['name']] == expected, f'Step {step["name"]!r} of {job} differs beyond the launcher call '
                    'and the declared edits')
        for key in common['jobs'][job]:
            if key not in ('steps', 'if') or (key == 'if' and job != 'preflight'):
                require(common['jobs'][job][key] == generated['jobs'][job][key], f'{job}.{key} differs')
    for job, first, second in ORDER:
        names = step_names(generated, job)
        require(names.index(first) < names.index(second), f'{first!r} must precede {second!r} in {job}')
    uploads = [step['uses'] for job in generated['jobs'].values() for step in job['steps']
               if 'upload' in step.get('uses', '')]
    require(uploads and set(uploads) == {PROTECTED_UPLOAD}, 'An upload does not use the protected action at its pin')
    trigger = generated.get('on', generated.get(True))
    require(set(trigger) == {'push', 'workflow_dispatch'} and trigger['push'] == {'branches': [line.DELIVERY_BRANCH]} and
            trigger['workflow_dispatch']['inputs']['build']['required'] is True, 'Unexpected trigger')
    for key in ('permissions', 'env'):
        require(common[key] == generated[key], key + ' differs')
    return dict(source=SOURCE, target=TARGET, jobs=list(generated['jobs']), insertedSteps=inserted,
                editedSteps=[dict(job=job, step=name, old=old, new=new) for job, name, old, new, _ in STEP_EDITS],
                launcherCalls=target_text.count(LINE_CALL), uploads=len(uploads), trigger=trigger,
                preflightGate=generated['jobs']['preflight']['if'], concurrency=generated['concurrency'])


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--explain', action='store_true')
    args = parser.parse_args(argv)
    source_text = (ROOT / SOURCE).read_text()
    text = generate(source_text)
    report = explain(source_text, text, line.load_recipe().load_yaml_subset)
    target = ROOT / TARGET
    if args.check:
        if not target.is_file() or target.read_text() != text:
            print(f'{TARGET} is not the workflow generated from {SOURCE}; regenerate it', file=sys.stderr)
            return 1
    elif not args.explain:
        target.write_text(text)
    print(json.dumps(report, indent=2))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
